; DB32 bootstrap RGB888 demo: a CPU-painted neon colour study.
; 160 x 120 x 3 bytes, generated by guest instructions in RAM.
.equ FB, 0x10000
.equ VIDEO, 0xf5000
.entry start

start:
    li r1, FB             ; current RGB byte address
    mov r2, r0            ; y
    li r4, 160
    li r5, 120
    li r12, 80            ; centre x
    li r13, 60            ; centre y
    li r14, 42            ; diamond radius
row:
    mov r3, r0            ; x
pixel:
    ; Three independent gradients, including an XOR interference field.
    li r9, 1
    shr r9, r2, r9
    add r6, r3, r9
    add r7, r2, r2
    li r9, 3
    shr r9, r3, r9
    add r7, r7, r9
    li r9, 1
    shl r9, r2, r9
    xor r8, r3, r9
    addi r8, r8, 40
    andi r8, r8, 255

    ; Manhattan-distance medallion at the centre.
    sub r11, r3, r12
    blt r11, r0, negate_x
distance_y:
    sub r10, r2, r13
    blt r10, r0, negate_y
distance_ready:
    add r11, r11, r10
    bltu r11, r14, medallion
    ; A 16-pixel lattice and bright nodes across the outer gradient.
    andi r9, r3, 15
    beq r9, r0, lattice
    andi r9, r2, 15
    bne r9, r0, write_rgb
lattice:
    li r6, 85
    li r7, 125
    li r8, 205
    andi r9, r3, 15
    bne r9, r0, write_rgb
    andi r9, r2, 15
    bne r9, r0, write_rgb
    li r6, 230
    li r7, 235
    li r8, 250
    j write_rgb
negate_x:
    sub r11, r0, r11
    j distance_y
negate_y:
    sub r10, r0, r10
    j distance_ready
medallion:
    li r9, 3
    mul r9, r11, r9
    li r6, 230
    sub r6, r6, r9
    li r9, 4
    mul r9, r11, r9
    addi r7, r9, 50
    add r9, r11, r11
    li r8, 250
    sub r8, r8, r9
    andi r9, r11, 7
    li r10, 2
    bltu r9, r10, luminous_ring
    j write_rgb
luminous_ring:
    li r6, 255
    li r7, 210
    li r8, 245
write_rgb:
    sb r6, 0(r1)
    sb r7, 1(r1)
    sb r8, 2(r1)
    addi r1, r1, 3
    addi r3, r3, 1
    bltu r3, r4, pixel
    addi r2, r2, 1
    bltu r2, r5, row

    ; The completed RGB buffer occupies RAM 0x10000..0x1e0ff.
    li r3, VIDEO
    li r1, FB
    sw r1, 0(r3)
    li r9, 480
    sw r9, 4(r3)
    li r9, 4            ; RGB888
    sw r9, 8(r3)
    li r9, 1
    sw r9, 16(r3)
    sw r9, 20(r3)
    halt
